contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // We accept parameters: target address to attempt sendMoney to, value to send from c, data payload,
    // and an amount to send into c via fallback (so depositsCount may increase).
    function run(address payable target, uint sendValue, bytes calldata data, uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Record initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Make c receive some ether via its fallback by directly sending value to it from this contract
        // (fallback increments depositsCount)
        if (depositAmount > 0) {
            (bool s,) = address(c).call{value: depositAmount}("");
            // if sending fails, depositsCount shouldn't change; allow both outcomes
        }

        uint midDeposits = c.depositsCount();
        uint midBal = address(c).balance;

        // Now attempt owner-only operations as this contract (note: this contract is NOT the original owner of C)
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrawReverted;
        try c.withdraw(sendValue) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, sendValue, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // After attempts, read final observable state
        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule asserted: if any of the owner-only calls reverted (which should happen when caller is not owner),
        // then none of those reverting calls may have decreased c.balance or changed depositsCount compared to mid-state.
        // Conversely, if any such call did NOT revert (meaning this contract is owner), then balance may have decreased,
        // but depositsCount must never decrease (fallback only increments).
        assert(
            // Case A: caller is not owner and calls reverted => deposits and balance unchanged from mid-state
            (
                (withdrewReverted || withdrawReverted || sendMoneyReverted) &&
                (afterDeposits >= midDeposits) &&
                (afterBal >= midBal)
            )
            ||
            // Case B: caller succeeded in at least one owner call => depositsCount not decreased relative to mid
            (
                !(withdrewReverted || withdrawReverted || sendMoneyReverted) &&
                (afterDeposits >= midDeposits)
            )
        );
    }

    // allow receiving Ether for test funding
    receive() external payable {}
}

