    // sendValue: value passed to withdraw/sendMoney
    // target, data: parameters for sendMoney
    function run(address payable target, uint sendValue, bytes calldata data, uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // observe before
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Make c receive Ether to possibly change depositsCount via fallback
        if (depositAmount > 0) {
            (bool ok,) = address(c).call{value: depositAmount}("");
            // succeed or fail: either way is allowed; depositsCount may increase only if succeeded
        }

        // observe mid-state
        uint midDeposits = c.depositsCount();
        uint midBal = address(c).balance;

        // Attempt owner-only calls from this contract. Each is a top-level statement.
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        bool withdrawReverted;
        try c.withdraw(sendValue) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, sendValue, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // observe after
        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule expressed as single assert:
        // - depositsCount is never decreased by any of these operations (fallback only increments),
        // - if any owner-only call reverted when invoked by this caller, then c.balance did not decrease compared to mid-state.
        // This captures that failed owner-only actions must not have transferred Ether out, and depositsCount never decreases.
        assert(
            (afterDeposits >= midDeposits) &&
            (
                (withdrewAllReverted || withdrawReverted || sendMoneyReverted) ? (afterBal >= midBal) : true
            )
        );
    }

    // allow receiving Ether to fund tests
    receive() external payable {}
}

