contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = msg.sender; }

    // We will test calls to withdraw, withdrawAll, and sendMoney with an arbitrary caller
    // The test function takes parameters that drive the calls and Ether amounts.
    function run(address caller, address payable target, uint sendAmount, uint withdrawAmount, uint depositAmount, bytes calldata data) public payable {
        require(true);
        // Ensure this contract has enough balance to forward deposits to C if needed
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount, "insufficient balance for deposit");
            // send Ether into C via its fallback by calling with empty data
            (bool ok,) = address(c).call{value: depositAmount}(new bytes(0));
            require(ok);
        }

        // Record C's balance and depositsCount before actions
        uint beforeBal = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Try to perform withdraw by 'caller' using low-level calls to simulate different callers.
        bool withdrawReverted;
        {
            // attempt withdraw(withdrawAmount)
            (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", withdrawAmount));
            withdrawReverted = !ok;
        }

        // Try withdrawAll
        bool withdrawAllReverted;
        {
            (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
            withdrawAllReverted = !ok;
        }

        // Try sendMoney from this test contract (which is not owner) to target
        bool sendMoneyReverted;
        {
            (bool ok, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, sendAmount, data));
            sendMoneyReverted = !ok;
        }

        // Now observe after-state
        uint afterBal = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Determine whether the deployer of C is this contract (InvMutTest) by querying owner getter
        address owner = c.owner();
        bool thisIsOwner = (owner == address(this));

        // General rule asserted:
        // - If this contract is not the owner, then any call to withdraw, withdrawAll, or sendMoney MUST have reverted.
        // - If this contract is the owner, then none of those calls should have reverted, and total balance change of C must equal:
        //     - decreased by withdrawAmount if withdraw succeeded (transfer to owner)
        //     - or decreased by beforeBal if withdrawAll succeeded
        //   Also depositsCount only increases via fallback deposit (we did at most one), so afterDeposits >= beforeDeposits.
        // Expressed compactly:
        assert(
            ( !thisIsOwner && withdrawReverted && withdrawAllReverted && sendMoneyReverted )
            ||
            (
                thisIsOwner
                && !sendMoneyReverted && !withdrawReverted && !withdrawAllReverted
                && (afterDeposits >= beforeDeposits)
                && (
                    // balance decreased appropriately: either withdrawAll caused full balance transfer, or withdraw decreased by withdrawAmount
                    (afterBal + withdrawAmount == beforeBal) || (afterBal == 0)
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public test entry. We take parameters to try deposits and owner actions.
    function run(address payable target, uint depositAmount, uint withdrawAmount, bytes calldata data) public payable {
        require(true);
        // If we want to deposit into c, forward Ether to its fallback by a plain call to c with value.
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount);
            // deposit via fallback
            c.fallback{value: depositAmount}();
        }

        // Observe before values
        uint beforeBal = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        address owner = c.owner();
        bool thisIsOwner = (owner == address(this));

        // Attempt owner-only actions as top-level calls, capturing revert via try/catch where needed.
        bool withdrawReverted;
        bool withdrawAllReverted;
        bool sendMoneyReverted;

        // withdraw(uint)
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // withdrawAll()
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // sendMoney(address,uint,bytes)
        try c.sendMoney(target, withdrawAmount, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Observe after values
        uint afterBal = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General invariant:
        // - If this contract is not owner, then all owner-only operations must have reverted.
        // - If this contract is owner, then none of the owner operations should revert, depositsCount never decreases,
        //   and balance decreases either by withdrawAmount (if withdraw called) or goes to zero (if withdrawAll called).
        assert(
            (
                !thisIsOwner
                && withdrawReverted
                && withdrawAllReverted
                && sendMoneyReverted
            )
            ||
            (
                thisIsOwner
                && !withdrawReverted
                && !withdrawAllReverted
                && !sendMoneyReverted
                && afterDeposits >= beforeDeposits
                && (
                    // Either withdrawAll emptied contract, or withdraw reduced by withdrawAmount
                    (afterBal == 0) || (afterBal + withdrawAmount == beforeBal)
                )
            )
        );
    }

    // allow receiving Ether if target forwards to us
    receive() external payable {}
}

