contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test: try to withdraw _value using withdraw, and also try withdrawAll; both can only succeed
    // when this contract is the owner of c. We observe address(c).balance and address(this).balance and
    // c.owner() and c.depositsCount() via public getters.

    function run(uint sendToFallback, uint withdrawValue, uint sendAsFallbackData) public payable {
        require(true);
        // Preconditions for sending Ether to c via fallback: ensure this contract has enough balance
        if (sendToFallback > 0) {
            require(address(this).balance >= sendToFallback);
            // send Ether to fallback by calling c with no data
            (bool sent,) = address(c).call{value: sendToFallback}(new bytes(0));
            // The fallback increments depositsCount only when invoked (and accepts Ether). Ensure call succeeded
            require(sent);
        }

        // Snapshot balances before attempts
        uint balC_before = address(c).balance;
        uint balThis_before = address(this).balance;
        address owner = c.owner();

        // Attempt withdraw via direct withdraw(_value)
        bool withdraw_reverted;
        try c.withdraw(withdrawValue) {
            withdraw_reverted = false;
        } catch {
            withdraw_reverted = true;
        }

        // Snapshot after first attempt
        uint balC_after_withdraw = address(c).balance;
        uint balThis_after_withdraw = address(this).balance;

        // Attempt withdrawAll
        bool withdrawAll_reverted;
        try c.withdrawAll() {
            withdrawAll_reverted = false;
        } catch {
            withdrawAll_reverted = true;
        }

        // Final snapshots
        uint balC_after = address(c).balance;
        uint balThis_after = address(this).balance;
        uint depositsCountNow = c.depositsCount();

        // General rule asserted:
        // 1) If this contract is owner, neither withdraw nor withdrawAll should revert, and balances change accordingly:
        //    - If withdraw succeeded then c's balance decreased by withdrawValue and this contract increased by same amount.
        //    - If withdrawAll succeeded then c's final balance is zero and this contract's balance increased by the amount pulled.
        // 2) If this contract is not owner, both calls must revert and no balances are transferred by them (only prior fallback send may have changed balance).
        assert(
            (
                address(this) == owner &&
                withdraw_reverted == false &&
                withdrawAll_reverted == false &&
                // For withdraw successful: balC_after_withdraw == balC_before - withdrawValue (unless withdrawValue > balC_before then transfer will revert, but owner can withdraw arbitrary value; however Solidity transfer will send up to balance — in this contract withdraw uses transfer which reverts if insufficient funds, so require withdrawValue <= balC_before)
                (withdrawValue <= balC_before ? balC_after_withdraw == balC_before - withdrawValue : balC_after_withdraw == balC_before) &&
                // withdrawal moved funds to this contract accordingly
                (withdrawValue <= balC_before ? balThis_after_withdraw == balThis_before + withdrawValue : balThis_after_withdraw == balThis_before) &&
                // After withdrawAll (owner) final c balance is zero and this contract gained the remaining funds
                balC_after == 0 && balThis_after == balThis_after_withdraw + balC_after_withdraw - balC_after_withdraw /* no-op but keeps expression consistent */
            ) ||
            (
                address(this) != owner &&
                withdraw_reverted == true &&
                withdrawAll_reverted == true &&
