contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try actions from two different callers simulated by making calls
    // from this contract; since this contract is the deployer of C in the checker,
    // it is the owner. We also allow arbitrary target addresses/data/values.

    // Single public function per spec
    function run(address target, uint value, bytes calldata data) public payable {
        require(address(this).balance >= value || value == 0);

        // Read initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // 1) Call fallback by sending Ether to C to increment depositsCount
        if (value > 0) {
            // send value to fallback
            (bool sent,) = address(c).call{value: value}("\x00");
            // require that the low-level call succeeded — if it reverted, then depositsCount must not have increased
        }

        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // 2) Try owner-only actions from this contract (which is owner). They SHOULD NOT revert.
        bool ownerWithdrawReverted;
        bool ownerWithdrawAllReverted;
        bool ownerSendReverted;

        try c.withdraw{ }(0) {
            ownerWithdrawReverted = false;
        } catch {
            ownerWithdrawReverted = true;
        }

        try c.withdrawAll{ }() {
            ownerWithdrawAllReverted = false;
        } catch {
            ownerWithdrawAllReverted = true;
        }

        try c.sendMoney{ }(target, 0, data) {
            ownerSendReverted = false;
        } catch {
            ownerSendReverted = true;
        }

        // 3) Try to simulate a non-owner call by using a callframe that changes msg.sender is impossible here,
        // so we instead assert the invariant: owner calls must not revert, and depositsCount increased exactly when balance increased.

        // General rule to assert:
        // - If the contract balance increased by some amount `delta` compared to beforeBal, then depositsCount increased by at least 1 and afterBal - beforeBal == value (the Ether we attempted to send).
        // - Owner-only functions invoked by this (owner) must not revert.

        bool ownerCallsSucceeded = !ownerWithdrawReverted && !ownerWithdrawAllReverted && !ownerSendReverted;

        // Note: afterDeposits >= beforeDeposits (fallback increments only), and balance difference equals value iff value>0 and call succeeded.
        uint balanceDiff = afterBal >= beforeBal ? afterBal - beforeBal : 0;
        bool depositsNonDecreasing = afterDeposits >= beforeDeposits;

        // Final single assert combining the general rule.
        assert(ownerCallsSucceeded && depositsNonDecreasing && (balanceDiff == 0 || (balanceDiff == value && afterDeposits == beforeDeposits + 1)));
    }

    // Allow this contract to receive Ether so it can fund calls
    receive() external payable {}
}

