contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = msg.sender; // deployer of InvMutTest (and originally C's constructor saw this address as owner)
    }

    // We will attempt calls as this contract (which is the msg.sender recorded in C.owner at deployment time).
    // To simulate non-owner calls, the test will rely on an external EOA calling this run(...) with different msg.sender,
    // but the checker runs run exactly once from a harness — so instead we check owner vs non-owner behaviour by
    // observing that calls made by this contract (the owner) must succeed and reduce address(c).balance, and
    // that attempted calls with zero requested value do not change balance. For a non-owner revert property we induce a revert
    // by calling functions from a nested call triggered by a low-level call from an externally-controlled helper address.

    // However, since the checker runs all calls with msg.sender = this contract, we assert the following general rule:
    // If this contract (the owner) calls withdraw(_v) or withdrawAll() or sendMoney(target,_v,data) and the call does not revert,
    // then address(c).balance after the call equals before minus the amount actually transferred out (which is <= requested _v),
    // and depositsCount increases only via fallback payable calls.

    // Single public function containing all logic.
    function run(address payable target, uint256 value, bytes calldata data, uint256 etherToSend) public payable {
        require(address(this).balance >= etherToSend);

        // Read before values
        uint256 beforeBalance = address(c).balance;
        uint256 beforeDeposits = c.depositsCount();

        // 1) Test fallback: send raw Ether to c to trigger fallback which increments depositsCount
        // Use send to trigger fallback on payable fallback — need to call c with value and no data
        if (etherToSend > 0) {
            // send Ether to c's fallback
            (bool s, ) = address(c).call{value: etherToSend}("\x00");
            // it's acceptable that this may revert or succeed depending on gas/use; proceed regardless
            // Read after fallback attempt
        }

        uint256 midBalance = address(c).balance;
        uint256 midDeposits = c.depositsCount();

        // 2) Owner tries withdraw(value)
        bool withdrewReverted;
        try c.withdraw(value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint256 afterWithdrawBalance = address(c).balance;

        // 3) Owner tries sendMoney(target, value, data)
        bool sendReverted;
        try c.sendMoney(target, value, data) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }
        uint256 afterSendBalance = address(c).balance;

        // 4) Owner tries withdrawAll()
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }
        uint256 finalBalance = address(c).balance;

        // Observations:
        // - depositsCount should have increased by the number of successful fallback payable invocations (i.e., if etherToSend>0 and the raw call succeeded).
        //   We cannot observe whether the raw call succeeded except via balance change; so assert monotonicity: depositsCount never decreases.
        // - Balances after owner-successful calls must be <= before and decreased by at most the value requested for each call that claimed success.
        // Construct the general rule as a single assert combining these.

        // Compute monotonicity for depositsCount
        bool depositsNotDecreased = (midDeposits >= beforeDeposits) && (c.depositsCount() >= midDeposits);

        // For each attempted outgoing call that did NOT revert, the corresponding balance drop is <= requested value and overall balance never increases due to these calls.
        // We conservatively check cumulative decreases: beforeBalance -> afterWithdrawBalance -> afterSendBalance -> finalBalance
        bool balancesNonIncreasingDuringActions = (afterWithdrawBalance <= midBalance) && (afterSendBalance <= afterWithdrawBalance) && (finalBalance <= afterSendBalance);

        // For each call that did not revert, ensure that the drop in balance attributable to that call is <= requested value.
        // Because other calls may also move funds, we check per-step decreases are <= the value used in that step.
        bool withdrawDropOkay = true;
        if (!withdrewReverted) {
            // drop from midBalance to afterWithdrawBalance should be <= value
            withdrawDropOkay = (midBalance - afterWithdrawBalance) <= value;
        }
        bool sendDropOkay = true;
        if (!sendReverted) {
            // drop from afterWithdrawBalance to afterSendBalance should be <= value
            sendDropOkay = (afterWithdrawBalance - afterSendBalance) <= value;
        }
        bool withdrawAllDropOkay = true;
        if (!withdrawAllReverted) {
            // drop from afterSendBalance to finalBalance should be <= afterSendBalance (i.e., cannot withdraw more than exists)
            withdrawAllDropOkay = (afterSendBalance - finalBalance) <= afterSendBalance;
        }

        assert(depositsNotDecreased && balancesNonIncreasingDuringActions && withdrawDropOkay && sendDropOkay && withdrawAllDropOkay);
    }

    receive() external payable {}
}

