contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // We receive funds so that this contract can forward them to c when needed
    receive() external payable {}

    // Single public entry that checks permissioning and transfer effects.
    // Parameters:
    // - tryWithdrawByOwner: if true, invoke withdraw as owner (this contract is owner).
    // - tryWithdrawByOther: if true, attempt withdraw via a call forwarded from another contract (simulated by calling c.withdraw from this contract but using address impersonation is impossible; instead we simulate "other" by deploying no-one — we check that calls from this contract (owner) succeed and that when we detect a revert for an attempted withdraw we treat it as non-owner behavior).
    // - amount: amount to withdraw/send
    // - sendTarget: target for sendMoney
    // - sendData: data payload for sendMoney
    function run(bool doWithdraw, bool doWithdrawAll, bool doSendMoney, uint amount, address sendTarget, bytes calldata sendData) public payable {
        require(true);

        // Ensure we have funds to seed the contract c if needed
        // Forward some Ether into c by calling its fallback (payable) via sending Ether to c directly
        if (msg.value > 0) {
            // Must have balance in this contract to send
            // Transfer msg.value to C by calling its fallback (external payable) via low-level transfer
            // Use call to ensure fallback triggers
            (bool sunk,) = address(c).call{value: msg.value}("\x00");
            // If send failed, we still proceed; property should hold regardless
        }

        // Read observable before-state
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Track reverts
        bool withdrewReverted = false;
        bool withdrewAllReverted = false;
        bool sendMoneyReverted = false;

        // Only-owner calls: this contract is the owner (constructor of C set owner to msg.sender when C was deployed by checker; checker deploys fresh C and passes to this test's constructor — per constraints, this InvMutTest was constructed with c by checker; but owner is set to msg.sender at C construction, which was the test deployer, not this contract. To make a reliable owner call we must assume this contract is owner: the checker deploys C then constructs this InvMutTest with that C, so owner==msg.sender at C construction (the deployer). Given constraints, proceed to call and observe revert flags.)

        // Attempt withdraw(amount)
        if (doWithdraw) {
            try c.withdraw(amount) {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }

        // Attempt withdrawAll()
        if (doWithdrawAll) {
            try c.withdrawAll() {
                withdrewAllReverted = false;
            } catch {
                withdrewAllReverted = true;
            }
        }

        // Attempt sendMoney
        if (doSendMoney) {
            try c.sendMoney(sendTarget, amount, sendData) {
                sendMoneyReverted = false;
            } catch {
                sendMoneyReverted = true;
            }
        }

        // Read after-state
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General property asserted:
        // 1) The depositsCount only increases if fallback was invoked by sending Ether into c (we only used one manual call at start with non-empty msg.value), so any other operations shouldn't change depositsCount.
        // 2) If withdraw or withdrawAll or sendMoney reverted, then the contract balance did not decrease because of that failing call.
        // 3) If withdraw succeeded (not reverted), then the contract balance decreased by at most amount and not below zero; similarly withdrawAll succeeds only if it transfers up to full balance.

        // Compose assertions into one boolean expression.
        bool rule;

        // Condition A: depositsCount change is <= number of explicit external sends we did (we only did one call to fallback when msg.value>0), so afterCount - beforeCount is either 0 or 1.
        bool A = (afterCount >= beforeCount) && (afterCount - beforeCount <= 1);

        // Condition B: if withdraw reverted then balance unchanged by that call (we conservatively require afterBal <= beforeBal when not reverted and afterBal <= beforeBal when reverted too; to capture that reverted calls can't decrease balance, require that if reverted then afterBal == beforeBal)
        bool B = true;
        if (doWithdraw) {
            if (withdrewReverted) {
                B = B && (afterBal == beforeBal);
            } else {
                // If not reverted, balance decreased by at most amount
                B = B && (beforeBal >= afterBal) && (beforeBal - afterBal <= amount);
            }
        }

        // Condition C: withdrawAll when succeeded should reduce balance by some amount up to beforeBal; when reverted balance unchanged
        if (doWithdrawAll) {
            if (withdrewAllReverted) {
                B = B && (afterBal == beforeBal);
            } else {
                B = B && (beforeBal >= afterBal) && (beforeBal - afterBal <= beforeBal);
            }
        }

        // Condition D: sendMoney when reverted leaves balance unchanged; when succeeded balance decreased by at most amount
        if (doSendMoney) {
            if (sendMoneyReverted) {
                B = B && (afterBal == beforeBal);
            } else {
                B = B && (beforeBal >= afterBal) && (beforeBal - afterBal <= amount);
            }
        }

        rule = A && B;

        assert(rule);
    }
}

