contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test function will attempt to call withdraw, withdrawAll, and sendMoney from this contract.
    // Since the deployer of C is msg.sender at C's construction (not this contract), these calls
    // should revert (onlyOwner) and therefore C's balance must remain unchanged by them.
    function run(address payable target, uint256 value, bytes calldata data, uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // Record C balance before any interactions
        uint256 before = address(c).balance;

        // Try withdrawAll
        bool revertedWithdrawAll;
        try c.withdrawAll{value: 0}() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Try withdraw(_value)
        bool revertedWithdraw;
        try c.withdraw{value: 0}(value) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Try sendMoney(_target, _value, _data) and also attempt sending Ether to C in the call
        bool revertedSendMoney;
        // ensure we have funds to forward when calling c.sendMoney which may transfer from C to target
        // We do not send Ether to c in this call (c will use its own balance), but we could include value=0
        try c.sendMoney{value: 0}(target, value, data) {
            revertedSendMoney = false;
        } catch {
            revertedSendMoney = true;
        }

        // Also attempt to trigger fallback by sending Ether to C
        bool revertedFallback;
        // sendAmount parameter is used to send ether to C's fallback; ensure we have it
        // We perform a low-level call to c.address to trigger fallback (this contract is not owner)
        revertedFallback = false;
        (bool ok,) = address(c).call{value: sendAmount}("");
        if(!ok) revertedFallback = true;

        uint256 after = address(c).balance;

        // General rule to assert:
        // If this InvMutTest contract is NOT the owner of C, then any attempts to invoke owner-only functions (withdrawAll, withdraw) must revert and must not decrease C's balance.
        // Additionally, sendMoney invoked from this contract must revert (owner-only) and not decrease C's balance because it should not have succeeded.
        // If the contract somehow is owner (which would only be true if C was constructed by this contract), then we do not assert reverts.

        // Check whether this contract is owner by reading c.owner()
        address owner = c.owner();
        if (owner != address(this)) {
            // When not owner: all owner-only calls should have reverted; fallback sending Ether may succeed and increase balance.
            // Therefore assert that none of the owner-only calls succeeded and that C's balance did not decrease due to them.
            // We assert that after >= before - 0 (i.e., after >= before) OR that any decrease is only due to successful non-owner actions (which shouldn't happen)
            // More precisely: if any owner-only call did not revert, that's a violation. Also, balance should be >= before unless fallback succeeded in adding funds.
            // Since fallback can only increase balance, a decrease implies a successful owner-only transfer which must not happen.
            assert(revertedWithdrawAll && revertedWithdraw && revertedSendMoney && after >= before);
        } else {
            // If this contract is owner, then the owner-only calls may succeed; in that case we cannot assert they reverted.
            // But we can still assert that fallback call's success corresponds to balance change: after - before == sendAmount
            // If the fallback call reverted, after should equal before. If it succeeded, after should equal before + sendAmount.
            if (revertedFallback) {
                assert(after == before);
            } else {
                assert(after == before + sendAmount);
            }
        }
    }

    // Allow contract to receive Ether so it can forward to C in the test
    receive() external payable {}
}

