    C c;
    constructor(C _c) { c = _c; }

    // Single public test function. Caller funds this contract if it wants it to forward Ether to c.
    function run(uint fundAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Fund c so it has some Ether to withdraw from, using a plain top-level call
        if (fundAmount > 0) {
            (bool ok, ) = address(c).call{value: fundAmount}("");
            require(ok);
        }

        // Observe pre-call state via public getters / balances
        uint beforeCbal = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        uint beforeMe = address(this).balance;

        // Attempt withdraw and record whether it reverted
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call state
        uint afterCbal = address(c).balance;
        uint afterDeposits = c.depositsCount();
        uint afterMe = address(this).balance;

        // General rule:
        // If withdraw did not revert then depositsCount must be unchanged,
        // and this contract's balance increase is <= withdrawAmount and equals the decrease in c's balance.
        // Also the decrease in c's balance cannot exceed the balance c had before the call.
        assert(reverted
               || (
                   afterDeposits == beforeDeposits
                   && beforeCbal >= afterCbal
                   && beforeCbal - afterCbal <= withdrawAmount
                   && afterMe >= beforeMe
                   && afterMe - beforeMe == beforeCbal - afterCbal
                 )
        );
    }

    // receive to accept Ether forwarded from c.withdraw
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function. Caller must fund this contract if it will forward Ether to c.
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // Observe pre-call state via public getters / balances
        uint beforeCbal = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Make a plain low-level call to trigger fallback on c and capture success
        bool ok;
        (ok, ) = address(c).call{value: sendAmount}("");

        // Observe post-call state
        uint afterCbal = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule:
        // - If the plain call succeeded then depositsCount increased by 1 and C's balance increased by exactly sendAmount.
        // - If the plain call reverted then depositsCount and C's balance are unchanged.
        assert(
            ok ? (afterDeposits == beforeDeposits + 1 && afterCbal == beforeCbal + sendAmount)
               : (afterDeposits == beforeDeposits && afterCbal == beforeCbal)
        );
    }

    // accept Ether forwarded from C when C executes transfers to this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry with parameters: choose a target, value, and calldata for sendMoney
    function run(address target, uint256 value, bytes calldata data) public payable {
        require(true);

        // Read who is the owner of c before any call
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // Attempt withdrawAll, withdraw and sendMoney and capture whether they revert
        bool reverted_withdrawAll;
        try c.withdrawAll() {
            reverted_withdrawAll = false;
        } catch {
            reverted_withdrawAll = true;
        }

        bool reverted_withdraw;
        try c.withdraw(value) {
            reverted_withdraw = false;
        } catch {
            reverted_withdraw = true;
        }

        bool reverted_sendMoney;
        // ensure we have enough balance to attempt sending value from c if the call would succeed
        // (we do not fund c here; sendMoney uses c.call so it uses c's balance)
        try c.sendMoney(target, value, data) {
            reverted_sendMoney = false;
        } catch {
            reverted_sendMoney = true;
        }

        // If any of the three calls succeeded (did not revert), then this contract must be the owner.
        // Also, if none succeeded, we permit that the caller is not the owner.
        bool anySucceeded = (!reverted_withdrawAll) || (!reverted_withdraw) || (!reverted_sendMoney);

        assert( anySucceeded == (ownerBefore == address(this)) );
    }

    // fallback to accept Ether if sent back during tests
    receive() external payable {}
}
